        return {"farmer": ["PASS"], "hands": [["PASS"]] * n_hands, "market": []}

    market = _g(obs, "market", None) or {}
    minv = dict(_g(market, "inventory", None) or {})
    prices = dict(_g(market, "prices", None) or {})
    for item in PRODUCTS:
